// Map circuit names from Ergast API to our track keys

// Aliases for alternate Ergast IDs
CIRCUIT_TRACKS["vegas"] = CIRCUIT_TRACKS["las_vegas"];
CIRCUIT_TRACKS["madrid"] = CIRCUIT_TRACKS["madring"];
CIRCUIT_TRACKS["madring"] = CIRCUIT_TRACKS["madring"];
CIRCUIT_TRACKS["sepang"] = CIRCUIT_TRACKS["sepang"];
CIRCUIT_TRACKS["losail"] = CIRCUIT_TRACKS["lusail"];

export function getCircuitKey(circuitName = "") {
  if (!circuitName) return "generic";
  const normalized = circuitName
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "") // remove accents
    .replace(/[\-_]/g, " ");

  if (normalized.includes("bahrain") || normalized.includes("sakhir")) return "bahrain";
  if (normalized.includes("jeddah") || normalized.includes("corniche") || normalized.includes("saudi")) return "jeddah";
  if (normalized.includes("albert park") || normalized.includes("melbourne") || normalized.includes("australia")) return "albert_park";
  if (normalized.includes("suzuka") || normalized.includes("japan")) return "suzuka";
  if (normalized.includes("shanghai") || normalized.includes("china")) return "shanghai";
  if (normalized.includes("miami")) return "miami";
  if (normalized.includes("imola") || normalized.includes("enzo") || normalized.includes("emilia")) return "imola";
  if (normalized.includes("monaco") || normalized.includes("monte carlo")) return "monaco";
  if (normalized.includes("villeneuve") || normalized.includes("montreal") || normalized.includes("canada")) return "villeneuve";
  if (normalized.includes("sepang") || normalized.includes("malaysia")) return "sepang";
  if (normalized.includes("madring") || normalized.includes("madrid") || normalized.includes("ifema")) return "madring";
  if (normalized.includes("barcelona") || normalized.includes("catalunya") || normalized.includes("spain")) return "catalunya";
  if (normalized.includes("red bull ring") || normalized.includes("spielberg") || normalized.includes("austria")) return "red_bull_ring";
  if (normalized.includes("silverstone") || normalized.includes("britain") || normalized.includes("british")) return "silverstone";
  if (normalized.includes("hungaroring") || normalized.includes("hungary") || normalized.includes("budapest")) return "hungaroring";
  if (normalized.includes("spa") || normalized.includes("francorchamps") || normalized.includes("belgium")) return "spa";
  if (normalized.includes("zandvoort") || normalized.includes("netherlands") || normalized.includes("dutch")) return "zandvoort";
  if (normalized.includes("monza") || normalized.includes("nazionale") || normalized.includes("italy")) return "monza";
  if (normalized.includes("baku") || normalized.includes("azerbaijan")) return "baku";
  if (normalized.includes("marina bay") || normalized.includes("singapore")) return "marina_bay";
  if (normalized.includes("americas") || normalized.includes("cota") || normalized.includes("austin")) return "cota";
  if (normalized.includes("rodriguez") || normalized.includes("mexico")) return "rodriguez";
  if (normalized.includes("interlagos") || normalized.includes("carlos pace") || normalized.includes("sao paulo") || normalized.includes("brazil")) return "interlagos";
  if (normalized.includes("vegas") || normalized.includes("nevada")) return "las_vegas";
  if (normalized.includes("lusail") || normalized.includes("losail") || normalized.includes("qatar")) return "lusail";
  if (normalized.includes("yas marina") || normalized.includes("abu dhabi") || normalized.includes("yas")) return "yas_marina";

  return "generic";
}

